content.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "graph-node.schema.json",
  "title": "dev-graph タスクグラフノード (draft)",
  "description": "run-plugin-dev-plan が manual-apply artifact として出力する schema draft。後段 builder または人手承認で plugins/dev-graph/schemas/graph-node.schema.json へ適用する。issue/task/specification/architecture/feature/document の各成果物を単一グラフ構造で表現し、issues/tasks/specs/architecture/features/docs の正規ディレクトリへ自動routingする。feature はマクロ層 (purpose/goal/scope/acceptance/architecture_refs) を保持し、細タスク仕様書生成は external plugin system-dev-planner (ミクロ層) へ委譲する (MM-01)。",
  "type": "object",
  "required": [
    "graph_node_id",
    "artifact_kind",
    "artifact_subtypes",
    "title",
    "project_id",
    "domain",
    "status",
    "owners",
    "tags",
    "priority",
    "start_date",
    "target_date",
    "iteration",
    "created_at",
    "updated_at",
    "depends_on",
    "related_nodes",
    "resource_scope",
    "parent_feature",
    "feature_package_id",
    "phase_ref",
    "file_path",
    "template_id",
    "template_version",
    "confirmation_status",
    "evaluation_status",
    "confirmation_evidence",
    "source_lineage",
    "classification_confidence",
    "classification_reason",
    "classification_candidates",
    "github_publication",
    "issue_linkage",
    "tracker_binding",
    "beads_linkage",
    "github_project_linkages",
    "pull_request_linkages",
    "execution_contexts",
    "completion_evidence",
    "implementation_readiness"
  ],
  "properties": {
    "graph_node_id": {
      "type": "string",
      "minLength": 1,
      "description": "移動・再分類・GitHub同期後も変化しない論理identity。file_pathはこのIDを参照する可変projectionでありidentityに使わない"
    },
    "id": {
      "type": "string",
      "deprecated": true,
      "description": "後方互換alias。新規成果物ではgraph_node_idを正本とする"
    },
    "artifact_kind": {
      ],
      "description": "artifact_kindから自動選択した基底テンプレート"
    },
    "template_version": {
      "type": "string",
      "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$",
      "description": "生成時に使用したテンプレート契約版。正本更新時は既存文書を全書換せずmigration previewへ使う"
    },
    "confirmation_status": {
      "type": "string",
      "enum": [
        "draft",
        "confirmed",
        "superseded"
      ],
      "description": "内容確定状態。system plan入力はspecification/architectureがconfirmedであることを要求する"
    },
    "evaluation_status": {
      "type": "string",
      "enum": [
        "pending",
        "pass",
        "fail",
        "stale"
      ],
      "description": "独立評価状態。C14/C15/C04はpass以外をIssue起票・推薦・実装handoff対象にしない"
    },
    "confirmation_evidence": {
      "type": "object",
      "required": [
        "evaluator",
        "evidence_ref",
        "evaluated_digest"
      ],
      "properties": {
        "evaluator": {
          "type": [
            "string",
            "null"
          ]
        },
        "evidence_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "evaluated_digest": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[a-f0-9]{64}$"
        }
      },
      "additionalProperties": false,
      "description": "confirmation/evaluationを同一artifact digestへpinしstale PASSを拒否する"
    },
    "source_lineage": {
      "type": "object",
      "required": [
        "origin_kind",
        "source_plugin",
        "source_path",
        "source_version",
        "source_digest",
        "imported_at"
      ],
      "properties": {
        "origin_kind": {
          "type": "string",
          "enum": [
            "manual",
            "github",
            "system-spec-harness",
            "system-dev-planner",
            "generated"
          ]
        },
        "source_plugin": {
          "type": [
            "string",
            "null"
          ]
        },
        "source_path": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
        },
        "source_version": {
          "type": [
            "string",
            "null"
          ]
        },
        "source_digest": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[a-f0-9]{64}$"
        },
        "imported_at": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        }
      },
      "additionalProperties": false,
      "description": "引用・import元を追跡し、C19およびexternal plugin system-dev-planner由来のimportが外部正本を利用したことを検証する"
    },
    "classification_confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "artifact_kind/domain/project_id自動分類のconfidence。0.80以上かつ第2候補との差0.15以上で自動確定、それ未満はpreview後に確認"
    },
    "classification_reason": {
      "type": "string",
      "minLength": 1,
      "description": "自動分類の根拠。previewと監査証跡へ表示する"
    },
    "classification_candidates": {
      "type": "array",
      "items": {
        "type": "object",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "implementation_readiness": {
      "type": "object",
      "required": [
        "status",
        "missing_sections",
        "checked_at"
      ],
      "properties": {
        "status": {
          "type": "string",
          "enum": [
            "complete",
            "incomplete",
            "not_applicable"
          ]
        },
        "missing_sections": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "uniqueItems": true
        },
        "checked_at": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        }
      },
      "additionalProperties": false,
      "description": "template-contract.jsonの必須field/section、placeholder、conditional template、参照解決を検査した実装着手準備状態"
    }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evaluation_status": {
            "const": "pass"
          }
        }
      },
      "then": {
        "properties": {
          "confirmation_status": {
            "const": "confirmed"
          },
          "confirmation_evidence": {
            "properties": {
              "evaluator": {
                "type": "string",
                "minLength": 1
              },
              "evidence_ref": {
                "type": "string",
                "minLength": 1
              },
              "evaluated_digest": {
                "type": "string",
                "pattern": "^[a-f0-9]{64}$"
              }
            }
          },
          "implementation_readiness": {
            "properties": {
              "status": {
                "const": "complete"
              },
              "missing_sections": {
                "maxItems": 0
              },
              "checked_at": {
                "type": "string",
                "format": "date-time"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "status": {
            "const": "active"
          }
        }
      },
      "then": {
        "properties": {
          "confirmation_status": {
            "const": "confirmed"
          },
          "evaluation_status": {
            "const": "pass"
          },
          "implementation_readiness": {
            "properties": {
              "status": {
                "const": "complete"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "github_publication": {
            "properties": {
              "mode": {
                "enum": [
                  "issue",
                  "issue_and_projects"
                ]
              }
            }
          }
        }
      },
      "then": {
        "properties": {
          "artifact_kind": {
            "enum": [
              "issue",
              "task"
            ]
          },
          "confirmation_status": {
            "const": "confirmed"
          },
          "evaluation_status": {
            "const": "pass"
          },
          "implementation_readiness": {
            "properties": {
              "status": {
                "const": "complete"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "completion_evidence": {
            "properties": {
              "status": {
                "const": "done"
              },
              "policy": {
                "const": "linked_pr_merged_all"
              }
            }
          }
        }
      },
      "then": {
        "properties": {
          "status": {
            "const": "done"
          },
          "pull_request_linkages": {
            "minItems": 1,
            "items": {
              "properties": {
                "state": {
                  "const": "merged"
                }
              }
            }
          },
          "completion_evidence": {
            "properties": {
              "completed_at": {
                "type": "string",
                "format": "date-time"
              },
              "reconciled_at": {
                "type": "string",
                "format": "date-time"
              },
              "source": {
                "const": "github_pr_merge"
              },
              "evidence_refs": {
                "minItems": 1
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "completion_evidence": {
            "properties": {
              "status": {
                "const": "done"
              },
              "policy": {
                "const": "linked_pr_merged_any"
              }
            }
          }
        }
      },
      "then": {
        "properties": {
          "status": {
            "const": "done"
          },
          "pull_request_linkages": {
            "minItems": 1,
            "contains": {
              "properties": {
                "state": {
                  "const": "merged"
                }
              }
            }
          },
          "completion_evidence": {
            "properties": {
              "completed_at": {
                "type": "string",
                "format": "date-time"
              },
              "reconciled_at": {
                "type": "string",
                "format": "date-time"
              },
              "source": {
                "const": "github_pr_merge"
              },
              "evidence_refs": {
                "minItems": 1
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "source_lineage": {
            "properties": {
              "origin_kind": {
                "enum": [
                  "system-spec-harness",
                  "system-dev-planner"
                ]
              }
            }
          }
        }
      },
      "then": {
        "properties": {
          "source_lineage": {
            "properties": {
              "source_plugin": {
                "type": "string",
